DROP TABLE IF EXISTS t_netelementlog CASCADE;

CREATE TABLE t_netelementlog (
   cseqno bigserial,
   cregisterno int NOT NULL,
   cserialno int NOT NULL,
   cnename varchar(255),
   cneip varchar(255),
   cnetype varchar(255),
   cusername varchar(255),
   coperterminal varchar(255),
   copername varchar(255),
   copertime timestamp,
   coperret varchar(255),
   cdetailinfo varchar(255),
   cnetypehash bigint,
   creservedint int,
   creserved varchar(1),
   CONSTRAINT pk_nelog_seqno PRIMARY KEY (cseqno)
)
;


CREATE INDEX ix_nelog_netypehash ON t_netelementlog (
cnetypehash ASC
);


CREATE INDEX ix_nelog_neip ON t_netelementlog (
cneip ASC
);


