cusername ASC
);


CREATE INDEX ix_nelog_operterminal ON t_netelementlog (
coperterminal ASC
);


CREATE INDEX ix_nelog_opername ON t_netelementlog (
copername ASC
);


CREATE INDEX ix_nelog_opertime ON t_netelementlog (
copertime ASC
);


CREATE INDEX ix_nelog_netype ON t_netelementlog (
cnetype ASC
);

